-- Routing test (2026-10-15): one simulated request per catalog specialty (132), inside a
-- transaction that is always rolled back. Checks every request reaches exactly the suppliers
-- count_matching_suppliers() expects, and lists the specialties no supplier covers yet.
-- Regenerate the sample list with catalog-audit/sub_samples.ts when the catalog changes.
begin;
alter table public.rfqs disable trigger trg_enforce_rfq_limit;
create temp table _ids(id uuid, sector text, sub text, name text);
select set_config('tsk.c', (select id::text from profiles where role='contractor' order by created_at limit 1), true);
create temp table _res as select i.*, public.count_matching_suppliers(r, r.items->0) expected, (select count(distinct n.user_id) from notifications n join profiles p on p.id=n.user_id where n.type='new_rfq' and n.data->>'rfq_id' = i.id::text and p.role::text='supplier' and not (n.data ? 'uncovered')) notified from _ids i join rfqs r on r.id=i.id;
select 'specialties tested: '||count(*)||' | reach >=1 supplier: '||count(*) filter (where notified>0)||' | reach nobody: '||count(*) filter (where notified=0)||' | expected<>notified: '||count(*) filter (where expected<>notified) from _res;
select 'MISMATCH '||sector||' '||sub||' '||name||' expected='||expected||' notified='||notified from _res where expected<>notified;
select 'NOBODY '||sector||' | '||sub||' | '||name from _res where notified=0 order by sector, sub;
rollback;
